def _prove_transverse_range_only(tree):
    """Fail closed if the chart's Valid output gains a non-range v dependency.

    Every longitudinal station remains on the retained grid perimeter. The
    omitted transverse samples are 1-col/nv with nv>=4 and 0<=col<=nv, so
    they satisfy the same strict enclosing range tests as the retained ends.
    Traversal is deliberately conservative across other nodes/group inputs.
    """
    output,=[n for n in tree.nodes if n.type=='GROUP_OUTPUT' and n.is_active_output]
    visited=set()
    def visit(socket):
        if socket in visited:return
        visited.add(socket);node=socket.node
        if node.type=='GROUP_INPUT':
            if socket.name=='v':raise ValueError('Chart validity has an unproved transverse dependency')
            return
        if node.bl_idname=='ShaderNodeMath' and node.operation in ('GREATER_THAN','LESS_THAN'):
            links=node.inputs[0].links
            if len(links)==1 and links[0].from_node.type=='GROUP_INPUT' and links[0].from_socket.name=='v':
                bound=node.inputs[1]
                enclosed=(node.operation=='GREATER_THAN' and bound.default_value<0.) or (
                    node.operation=='LESS_THAN' and bound.default_value>1.)
                if not bound.is_linked and enclosed:return
        for inp in node.inputs:
            for link in inp.links:visit(link.from_socket)
    for link in output.inputs['Valid'].links:visit(link.from_socket)


def guide_key(g,owner,row,count,sides):
    last=g.math('GREATER_THAN',row,count-.5)
    return g.xyz(0.,c.choose(g,last,g.math('MODULO',owner+1.,sides),owner),c.choose(g,last,0.,row))


def _corner_guide_records(g,sample,mouths,owner,nu,sides,datum,collapsed):
    """Keep the guide boundary of the former center, never its interior.

    The cyclic Coons blocks contribute one copy of each guide station, and
    two copies of its midpoint. Crowns belong to the next side at its first
    station. Retaining those multiplicities preserves identity-weld averaging.
    Every chart station is still checked, including the omitted last copy.
    """
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    crown=g.math('LESS_THAN',index,.5)
    key=guide_key(g,owner,index,nu,sides)
    fixed=g.math('MAXIMUM',crown,collapsed)
    valid=c._stat(g,sample,c.named(g,'st_ct_valid','BOOLEAN'))
    pin=datum+c.choose(g,crown,c._read(g,mouths,'st_cj_rise',owner),c.named(g,'st_ct_edge_rise'))
    records=g.setpos(sample,c.named(g,'st_ct_guide','FLOAT_VECTOR'))
    records=backend_weld.tag(g,records,key,True,crown)
    for attr,value,kind in (('key',key,'FLOAT_VECTOR'),('fixed',fixed,'BOOLEAN'),
            ('height_pinned',fixed,'BOOLEAN'),('pinned_height',pin,'FLOAT'),
            ('patch',0,'INT'),('field_valid',valid,'BOOLEAN')):
        records=c._store(g,records,'st_cq_'+attr,value,kind)
    midpoint=c._select(g,records,g.math('COMPARE',index,nu*.5))
    records=c._select(g,records,g.math('LESS_THAN',index,nu-.5))
    return boundary._join(g,records,midpoint)


